{
  "items": [
    {
      "title": "Destatis GENESIS-Online: Migration Between Germany and Foreign Countries by Citizenship (2000–2025)",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/table/12711-0007/table-toolbar",
      "justification": "Official migration dataset from Germany's Federal Statistical Office (Destatis). Provides annual immigration and emigration figures by citizenship, covering the entire 2020–2025 period. Particularly useful for analyzing migration trends, net migration, and changes in countries of origin during the COVID-19 pandemic and subsequent years."
    },
    {
      "title": "Destatis: Migration Flows Across Germany's Borders by Country of Birth (2022–2025)",
      "url_or_doi": "https://www.destatis.de/EN/Themes/Society-Environment/Population/Migration/Tables/migration-year-04.html",
      "justification": "Official statistical tables documenting migration into and out of Germany between 2022 and 2025, categorized by country of birth. Particularly relevant for examining migration following Russia's invasion of Ukraine in 2022 and comparing migration patterns across different origin countries."
    },
    {
      "title": "Destatis GENESIS-Online: Foreign Population by Citizenship, Sex, and Register Movements",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/statistic/12521/table/12521-0009",
      "justification": "Official German administrative statistics on foreign nationals, including register movements, citizenship categories, and demographic characteristics. Useful for studying changes in Germany's foreign population during the 2020s and distinguishing migration-related developments across nationality groups."
    },
    {
      "title": "Eurostat: Immigration by Age Group, Sex, and Citizenship (migr_imm1ctz)",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/view/migr_imm1ctz/default/table?lang=en",
      "justification": "Harmonized European statistical dataset containing annual immigration figures disaggregated by age, sex, and citizenship. Users can filter for Germany and years from 2020 onward. Particularly useful for studying the demographic characteristics of immigrants and comparing German immigration trends with those of other European countries."
    },
    {
      "title": "Eurostat: Emigration by Age Group, Sex, and Country of Next Residence (migr_emi3nxt)",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/view/migr_emi3nxt/default/table?category=migr.migr_cit.migr_emi&lang=en",
      "justification": "European statistical dataset documenting emigration from Germany and other European countries by age, sex, and destination country. Relevant for examining outward migration during the 2020s, identifying major destination countries, and understanding migration flows between Germany and other countries."
    },
    {
      "title": "Eurostat: International Migration and Citizenship Statistics",
      "url_or_doi": "https://ec.europa.eu/eurostat/en/web/migration-asylum/international-migration-citizenship/information-data",
      "justification": "Official Eurostat data portal providing access to multiple migration datasets, including immigration, emigration, citizenship acquisition, and migrant population statistics. Contains Germany-specific data for the 2020s and supports comparative European migration research. Particularly valuable for researchers seeking standardized migration indicators and methodological documentation."
    },
    {
      "title": "German Microcensus: Individual and Household Migration Characteristics (2020s)",
      "url_or_doi": "https://www.forschungsdatenzentrum.de/en/household/microcensus",
      "justification": "Large-scale representative household survey conducted by Germany's statistical authorities. Includes information on immigration history, demographic characteristics, employment, education, and household conditions. Particularly useful for studying the socioeconomic integration of immigrants during the 2020s. Research microdata are available through designated research data centers, subject to access conditions."
    },
    {
      "title": "DeZIM.panel: Longitudinal Survey Data on Migration and Integration in Germany",
      "url_or_doi": "https://doi.org/10.34882/dezim.panel.download.4.0.0",
      "justification": "Longitudinal research dataset from the German Center for Integration and Migration Research (DeZIM). Covers individuals living in Germany with and without migration histories. Particularly valuable for studying integration, social attitudes, discrimination, identity, and changes in migrant experiences over time during the 2020s. Scientific-use data are available through the DeZIM research data infrastructure."
    },
    {
      "title": "DeZIM Research Data Center: Migration and Integration Research Datasets",
      "url_or_doi": "https://datasearch.fdz.dezim-institut.de/",
      "justification": "Research data catalog specializing in migration, integration, and diversity in Germany. Provides metadata and access information for empirical datasets, including longitudinal surveys and studies of people with migration histories. Useful for identifying individual-level datasets covering social integration, discrimination, political attitudes, and migrant experiences during the 2020s."
    },
    {
      "title": "German Federal Office for Migration and Refugees (BAMF): Migration Report 2024",
      "url_or_doi": "https://doi.org/10.48570/bamf.fz.mb.2024.d.2026.migrationsbericht.1.0",
      "justification": "Official German government migration report containing extensive statistical tables and analyses of immigration and emigration in 2024, including migration by citizenship, countries of origin, migration categories, and asylum-related developments. Particularly useful as a consolidated source of administrative migration statistics, although it is a statistical report rather than a standalone machine-readable dataset."
    },
    {
      "title": "Destatis: Migration Statistics and Historical Time Series for Germany",
      "url_or_doi": "https://www.destatis.de/DE/Themen/Gesellschaft-Umwelt/Bevoelkerung/Wanderungen/_inhalt.html",
      "justification": "Official German statistical portal providing migration indicators and access to detailed migration datasets. Includes immigration, emigration, net migration, and historical time series extending through the 2020s. Useful for identifying national migration trends, assessing the effects of major events, and locating additional official statistical tables."
    },
    {
      "title": "Eurostat: Immigration Statistics and Dataset Metadata",
      "url_or_doi": "https://ec.europa.eu/eurostat/cache/metadata/en/migr_immi_esms.htm",
      "justification": "Official documentation for Eurostat's international immigration datasets. Explains statistical definitions, geographic coverage, data collection methods, comparability, and limitations. Particularly useful for researchers working with German migration data from 2020 onward who need to assess data quality and interpret differences between national and European migration statistics."
    }
  ]
}
